{
  "WPFTweaksDisableGameDVR": {
    "title": "Desativar Xbox Game DVR e Grava\u00e7\u00e3o em 2\u00ba Plano",
    "category": "Desempenho & Energia",
    "description": "Desativa a grava\u00e7\u00e3o cont\u00ednua de tela do Xbox Game Bar, reduzindo o uso de GPU/V\u00eddeo e eliminando micro-stutterings em jogos.",
    "rationale": "O recurso Historical Capture mant\u00e9m sess\u00f5es de codifica\u00e7\u00e3o de v\u00eddeo (NVENC/AMF) e buffers D3D ativos em segundo plano. Desativ\u00e1-lo preserva a Xbox Game Bar para convites de amigos, mas impede grava\u00e7\u00e3o cont\u00ednua involunt\u00e1ria. Fonte: Documenta\u00e7\u00e3o Microsoft Policy CSP ApplicationManagement/AllowGameDVR.",
    "impact": "M\u00e9dio",
    "riskLevel": "Safe",
    "osSupport": ["Win10", "Win11"],
    "minBuild": null,
    "requiresReboot": false,
    "confirmMessage": null,
