$script:EmbeddedThemeXaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="redimo &#x2014; System &amp; Gaming Optimizer"
        Width="1180" Height="820"
        MinWidth="980" MinHeight="680"
        WindowStartupLocation="CenterScreen"
        Background="#121212"
        Foreground="#F3F4F6"
        FontFamily="Segoe UI">

    <Window.Resources>
        <SolidColorBrush x:Key="BgPrimary" Color="#121212" />
        <SolidColorBrush x:Key="BgCard" Color="#1E1E1E" />
        <SolidColorBrush x:Key="BgSurface" Color="#18181B" />
        <SolidColorBrush x:Key="BorderSubtle" Color="#2D2D32" />
        <SolidColorBrush x:Key="AccentCyan" Color="#00E5FF" />
        <SolidColorBrush x:Key="AccentRed" Color="#FF4655" />
        <SolidColorBrush x:Key="TextPrimary" Color="#F3F4F6" />
        <SolidColorBrush x:Key="TextMuted" Color="#9CA3AF" />

        <Style x:Key="ActionButtonStyle" TargetType="Button">
            <Setter Property="Background" Value="#27272A" />
            <Setter Property="Foreground" Value="#F3F4F6" />
            <Setter Property="BorderBrush" Value="#3F3F46" />
            <Setter Property="BorderThickness" Value="1" />
            <Setter Property="Padding" Value="14,7" />
            <Setter Property="FontSize" Value="13" />
            <Setter Property="FontWeight" Value="SemiBold" />
            <Setter Property="Cursor" Value="Hand" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="btnBorder"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}"
                                CornerRadius="5"
                                Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" />
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="btnBorder" Property="BorderBrush" Value="#00E5FF" />
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="btnBorder" Property="Opacity" Value="0.45" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="PrimaryCyanButtonStyle" TargetType="Button" BasedOn="{StaticResource ActionButtonStyle}">
            <Setter Property="Background" Value="#00E5FF" />
            <Setter Property="Foreground" Value="#090D16" />
            <Setter Property="BorderBrush" Value="#00E5FF" />
            <Setter Property="FontWeight" Value="Bold" />
        </Style>

        <Style x:Key="DangerRedButtonStyle" TargetType="Button" BasedOn="{StaticResource ActionButtonStyle}">
            <Setter Property="Background" Value="#2A1619" />
            <Setter Property="Foreground" Value="#FF6B78" />
            <Setter Property="BorderBrush" Value="#FF4655" />
        </Style>

        <Style TargetType="TabItem">
            <Setter Property="Foreground" Value="#9CA3AF" />
            <Setter Property="FontSize" Value="14" />
            <Setter Property="FontWeight" Value="SemiBold" />
            <Setter Property="Padding" Value="16,10" />
            <Setter Property="Margin" Value="0,0,6,0" />
            <Setter Property="Cursor" Value="Hand" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TabItem">
                        <Border x:Name="tabBorder"
                                Background="#1A1A1E"
                                BorderBrush="#2D2D32"
                                BorderThickness="1,1,1,0"
                                CornerRadius="6,6,0,0"
                                Padding="{TemplateBinding Padding}"
                                Margin="{TemplateBinding Margin}">
                            <ContentPresenter ContentSource="Header" HorizontalAlignment="Center" VerticalAlignment="Center" />
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter TargetName="tabBorder" Property="Background" Value="#1E1E1E" />
                                <Setter TargetName="tabBorder" Property="BorderBrush" Value="#00E5FF" />
                                <Setter TargetName="tabBorder" Property="BorderThickness" Value="1,2,1,0" />
                                <Setter Property="Foreground" Value="#00E5FF" />
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter Property="Foreground" Value="#F3F4F6" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style TargetType="ToolTip">
            <Setter Property="Background" Value="#18181B" />
            <Setter Property="Foreground" Value="#F3F4F6" />
            <Setter Property="BorderBrush" Value="#00E5FF" />
            <Setter Property="BorderThickness" Value="1" />
            <Setter Property="Padding" Value="10,8" />
            <Setter Property="MaxWidth" Value="460" />
        </Style>
    </Window.Resources>

    <Grid Margin="16">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto" />
            <RowDefinition Height="*" />
            <RowDefinition Height="Auto" />
        </Grid.RowDefinitions>

        <!-- Cabe&#x00E7;alho Superior -->
        <Border Grid.Row="0" Background="#1E1E1E" BorderBrush="#2D2D32" BorderThickness="1" CornerRadius="8" Padding="16,12" Margin="0,0,0,12">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*" />
                    <ColumnDefinition Width="Auto" />
                </Grid.ColumnDefinitions>

                <StackPanel Grid.Column="0" Orientation="Vertical">
                    <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                        <TextBlock Text="redimo" FontSize="22" FontWeight="Bold" Foreground="#00E5FF" Margin="0,0,10,0" />
                        <TextBlock Text="System &amp; Gaming Optimizer" FontSize="15" FontWeight="SemiBold" Foreground="#E4E4E7" VerticalAlignment="Bottom" Margin="0,0,12,2" />
                        <Border Name="BadgeDryRun" Background="#3B2F0B" BorderBrush="#F59E0B" BorderThickness="1" CornerRadius="4" Padding="8,2" Visibility="Collapsed" VerticalAlignment="Center">
                            <TextBlock Text="MODO DRY-RUN (SIMULA&#x00C7;&#x00C3;O)" FontSize="11" FontWeight="Bold" Foreground="#FBBF24" />
                        </Border>
                    </StackPanel>
                    <TextBlock Name="TxtHardwareSummary" Text="Detectando configura&#x00E7;&#x00E3;o de hardware..." FontSize="12" Foreground="#9CA3AF" Margin="0,4,0,0" />
                </StackPanel>

                <!-- Barra de Busca R&#x00E1;pida -->
                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                    <Border Background="#121212" BorderBrush="#3F3F46" BorderThickness="1" CornerRadius="5" Padding="8,4" Width="280">
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="Auto" />
                                <ColumnDefinition Width="*" />
                            </Grid.ColumnDefinitions>
                            <TextBlock Grid.Column="0" Text="&#x1F50D;" Foreground="#9CA3AF" VerticalAlignment="Center" Margin="0,0,6,0" />
                            <TextBox Name="TxtSearchBox" Grid.Column="1" Background="Transparent" Foreground="#F3F4F6" CaretBrush="#00E5FF" BorderThickness="0" FontSize="13" VerticalAlignment="Center" ToolTip="Filtrar aplicativos, tweaks ou otimiza&#x00E7;&#x00F5;es por nome ou descri&#x00E7;&#x00E3;o" />
                        </Grid>
                    </Border>
                    <Button Name="BtnClearSearch" Content="Limpar" Style="{StaticResource ActionButtonStyle}" Margin="8,0,0,0" Padding="10,5" />
                </StackPanel>
            </Grid>
        </Border>

        <!-- &#x00C1;rea Central em Abas -->
        <TabControl Name="MainTabControl" Grid.Row="1" Background="#18181B" BorderBrush="#2D2D32" BorderThickness="1" Padding="10">
            <!-- Aba 1: Instalar Apps -->
            <TabItem Header="&#x1F4E6; Instalar Apps">
                <Grid>
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>
                    <Border Grid.Row="0" Background="#1E1E1E" BorderBrush="#2D2D32" BorderThickness="1" CornerRadius="6" Padding="12,8" Margin="0,0,0,10">
                        <DockPanel LastChildFill="False">
                            <TextBlock DockPanel.Dock="Left" Text="Selecione os aplicativos para instala&#x00E7;&#x00E3;o silenciosa via Winget. Pacotes j&#x00E1; instalados ser&#x00E3;o atualizados ou mantidos sem erro." Foreground="#D4D4D8" VerticalAlignment="Center" FontSize="12.5" />
                            <Button Name="BtnUncheckAllApps" DockPanel.Dock="Right" Content="Desmarcar Apps" Style="{StaticResource ActionButtonStyle}" Padding="10,4" FontSize="12" />
                        </DockPanel>
                    </Border>
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel Name="AppsCategoriesHost" Orientation="Vertical" Margin="0,0,6,0" />
                    </ScrollViewer>
                </Grid>
            </TabItem>

            <!-- Aba 2: Otimiza&#x00E7;&#x00F5;es & Debloat -->
            <TabItem Header="&#x26A1; Otimiza&#x00E7;&#x00F5;es &amp; Debloat">
                <Grid>
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>
                    <Border Grid.Row="0" Background="#1E1E1E" BorderBrush="#2D2D32" BorderThickness="1" CornerRadius="6" Padding="12,8" Margin="0,0,0,10">
                        <DockPanel LastChildFill="False">
                            <StackPanel DockPanel.Dock="Left" Orientation="Horizontal" VerticalAlignment="Center">
                                <TextBlock Text="Filosofia Anti-Placebo: passe o mouse sobre qualquer ajuste para ver a justificativa t&#x00E9;cnica e fonte." Foreground="#D4D4D8" FontSize="12.5" VerticalAlignment="Center" Margin="0,0,14,0" />
                                <TextBlock Text="&#x25CF; Aplicado na m&#x00E1;quina" Foreground="#10B981" FontSize="12" FontWeight="SemiBold" VerticalAlignment="Center" />
                            </StackPanel>
                            <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                                <Button Name="BtnRefreshState" Content="Atualizar Estado" Style="{StaticResource ActionButtonStyle}" Padding="10,4" FontSize="12" Margin="0,0,6,0" />
                                <Button Name="BtnUncheckAllTweaks" Content="Desmarcar Tweaks" Style="{StaticResource ActionButtonStyle}" Padding="10,4" FontSize="12" />
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel Name="TweaksCategoriesHost" Orientation="Vertical" Margin="0,0,6,0" />
                    </ScrollViewer>
                </Grid>
            </TabItem>

            <!-- Aba 3: Perfis de Jogos -->
            <TabItem Header="&#x1F3AE; Perfis de Jogos (Game Optimizer)">
                <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                    <StackPanel Name="GameProfilesHost" Orientation="Vertical" Margin="0,0,6,0" />
                </ScrollViewer>
            </TabItem>

            <!-- Aba 4: Manuten&#x00E7;&#x00E3;o & Reparo -->
            <TabItem Header="&#x1F6E0;&#xFE0F; Manuten&#x00E7;&#x00E3;o &amp; Reparo">
                <Grid>
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>

                    <!-- A&#x00E7;&#x00F5;es R&#x00E1;pidas de Manuten&#x00E7;&#x00E3;o -->
                    <Border Grid.Row="0" Background="#1E1E1E" BorderBrush="#2D2D32" BorderThickness="1" CornerRadius="6" Padding="14" Margin="0,0,0,12">
                        <StackPanel Orientation="Vertical">
                            <TextBlock Text="Ferramentas de Diagn&#x00F3;stico, Limpeza e Reparo do Sistema" FontSize="15" FontWeight="Bold" Foreground="#00E5FF" Margin="0,0,0,10" />
                            <WrapPanel Orientation="Horizontal">
                                <Button Name="BtnResetNetwork" Content="&#x1F310; Reset de Rede e DNS (Winsock / TCP-IP)" Style="{StaticResource ActionButtonStyle}" Margin="0,0,10,8" />
                                <Button Name="BtnRunSfcDism" Content="&#x1FA7A; Executar SFC /scannow + DISM /RestoreHealth" Style="{StaticResource ActionButtonStyle}" Margin="0,0,10,8" />
                                <Button Name="BtnCancelMaintenance" Content="&#x23F9; Cancelar SFC/DISM" Style="{StaticResource DangerRedButtonStyle}" Margin="0,0,10,8" IsEnabled="False" />
                                <Button Name="BtnClearTemp" Content="&#x1F9F9; Limpar Arquivos Tempor&#x00E1;rios (%TEMP%)" Style="{StaticResource ActionButtonStyle}" Margin="0,0,10,8" />
                                <Button Name="BtnOpenBackupsDir" Content="&#x1F4C2; Abrir Pasta de Backups e Logs" Style="{StaticResource ActionButtonStyle}" Margin="0,0,0,8" />
                            </WrapPanel>
                        </StackPanel>
                    </Border>

                    <!-- Gerenciador de Inicializa&#x00E7;&#x00E3;o -->
                    <Border Grid.Row="1" Background="#1E1E1E" BorderBrush="#2D2D32" BorderThickness="1" CornerRadius="6" Padding="14">
                        <Grid>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="Auto" />
                                <RowDefinition Height="*" />
                            </Grid.RowDefinitions>

                            <DockPanel Grid.Row="0" LastChildFill="False" Margin="0,0,0,10">
                                <StackPanel DockPanel.Dock="Left" Orientation="Vertical">
                                    <TextBlock Text="Gerenciador de Inicializa&#x00E7;&#x00E3;o do Windows (StartupApproved)" FontSize="15" FontWeight="Bold" Foreground="#F3F4F6" />
                                    <TextBlock Text="Controla programas que iniciam com o Windows usando o mesmo registro revers&#x00ED;vel do Gerenciador de Tarefas." FontSize="12" Foreground="#9CA3AF" />
                                </StackPanel>
                                <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                                    <Button Name="BtnEnableStartup" Content="Ativar Selecionado" Style="{StaticResource ActionButtonStyle}" Padding="10,5" Margin="0,0,6,0" />
                                    <Button Name="BtnDisableStartup" Content="Desativar Selecionado" Style="{StaticResource DangerRedButtonStyle}" Padding="10,5" Margin="0,0,6,0" />
                                    <Button Name="BtnRefreshStartup" Content="Recarregar" Style="{StaticResource ActionButtonStyle}" Padding="10,5" />
                                </StackPanel>
                            </DockPanel>

                            <DataGrid Name="GridStartupItems"
                                      Grid.Row="1"
                                      AutoGenerateColumns="False"
                                      IsReadOnly="True"
                                      SelectionMode="Single"
                                      Background="#121212"
                                      Foreground="#F3F4F6"
                                      RowBackground="#18181B"
                                      AlternatingRowBackground="#1E1E24"
                                      BorderBrush="#2D2D32"
                                      GridLinesVisibility="Horizontal"
                                      HorizontalGridLinesBrush="#27272A"
                                      HeadersVisibility="Column">
                                <DataGrid.Resources>
                                    <Style TargetType="DataGridColumnHeader">
                                        <Setter Property="Background" Value="#27272A" />
                                        <Setter Property="Foreground" Value="#00E5FF" />
                                        <Setter Property="FontWeight" Value="SemiBold" />
                                        <Setter Property="Padding" Value="10,6" />
                                        <Setter Property="BorderBrush" Value="#3F3F46" />
                                        <Setter Property="BorderThickness" Value="0,0,1,1" />
                                    </Style>
                                </DataGrid.Resources>
                                <DataGrid.Columns>
                                    <DataGridTextColumn Header="Estado" Binding="{Binding StatusText}" Width="100" />
                                    <DataGridTextColumn Header="Programa" Binding="{Binding Name}" Width="220" />
                                    <DataGridTextColumn Header="Escopo" Binding="{Binding Scope}" Width="190" />
                                    <DataGridTextColumn Header="Comando / Caminho" Binding="{Binding Command}" Width="*" />
                                </DataGrid.Columns>
                            </DataGrid>
                        </Grid>
                    </Border>
                </Grid>
            </TabItem>
        </TabControl>

        <!-- Barra Inferior Fixa -->
        <Border Grid.Row="2" Background="#1E1E1E" BorderBrush="#2D2D32" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,12,0,0">
            <Grid>
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto" />
                    <RowDefinition Height="Auto" />
                    <RowDefinition Height="Auto" />
                </Grid.RowDefinitions>

                <!-- Controles de Preset e A&#x00E7;&#x00E3;o -->
                <DockPanel Grid.Row="0" LastChildFill="False" Margin="0,0,0,10">
                    <StackPanel DockPanel.Dock="Left" Orientation="Horizontal" VerticalAlignment="Center">
                        <TextBlock Text="Preset:" FontWeight="SemiBold" Foreground="#D4D4D8" VerticalAlignment="Center" Margin="0,0,8,0" />
                        <ComboBox Name="CmbPresets" Width="210" Height="32" VerticalContentAlignment="Center" Background="#121212" Foreground="#121212" FontSize="13" Margin="0,0,8,0" />
                        <Button Name="BtnClearSelection" Content="Limpar Sele&#x00E7;&#x00E3;o" Style="{StaticResource ActionButtonStyle}" Padding="10,5" Margin="0,0,8,0" />
                        <TextBlock Name="TxtSelectionCounter" Text="0 itens selecionados" Foreground="#00E5FF" FontWeight="SemiBold" VerticalAlignment="Center" Margin="4,0,0,0" />
                    </StackPanel>

                    <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                        <Button Name="BtnViewApplied" Content="Ver Altera&#x00E7;&#x00F5;es Aplicadas" Style="{StaticResource ActionButtonStyle}" Margin="0,0,8,0" />
                        <Button Name="BtnUndoSelected" Content="Reverter Selecionados (Undo)" Style="{StaticResource DangerRedButtonStyle}" Margin="0,0,8,0" />
                        <Button Name="BtnApplySelected" Content="Aplicar Selecionados" Style="{StaticResource PrimaryCyanButtonStyle}" />
                    </StackPanel>
                </DockPanel>

                <!-- Barra de Progresso + Status -->
                <Grid Grid.Row="1" Margin="0,0,0,8">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="260" />
                        <ColumnDefinition Width="*" />
                    </Grid.ColumnDefinitions>
                    <ProgressBar Name="MainProgressBar" Grid.Column="0" Height="14" Minimum="0" Maximum="100" Value="0" Background="#121212" Foreground="#00E5FF" BorderBrush="#2D2D32" Margin="0,0,12,0" />
                    <TextBlock Name="TxtStatusMessage" Grid.Column="1" Text="Pronto. Selecione um preset ou marque os itens desejados." Foreground="#9CA3AF" FontSize="12" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" />
                </Grid>

                <!-- Console em Tempo Real -->
                <Border Grid.Row="2" Background="#0D0D10" BorderBrush="#27272A" BorderThickness="1" CornerRadius="5" Padding="6">
                    <TextBox Name="TxtConsoleOutput"
                             Height="92"
                             IsReadOnly="True"
                             TextWrapping="Wrap"
                             VerticalScrollBarVisibility="Auto"
                             Background="Transparent"
                             Foreground="#A1A1AA"
                             BorderThickness="0"
                             FontFamily="Consolas"
                             FontSize="11.5" />
                </Border>
            </Grid>
        </Border>
    </Grid>
</Window>
'@

# ============================================================================
# Module: src/windows/core/logger.ps1
# ============================================================================
# Sistema de logs, estado de execu--o e ponto -nico de muta--o (DryRun / Auditoria)

if (-not $script:Redimo) {
    $defaultRoot = Join-Path $env:ProgramData 'redimo'
    $script:Redimo = @{
        DataRoot      = $defaultRoot
        LogsDir       = Join-Path $defaultRoot 'logs'
        BackupsDir    = Join-Path $defaultRoot 'backups'
        StateFile     = Join-Path $defaultRoot 'state.json'
        LogFile       = $null
        DryRun        = $false
        SessionId     = (Get-Date -Format 'yyyy-MM-dd_HH-mm-ss')
        SessionDir    = $null
        SyncHash      = $null
        LogHistory    = New-Object 'System.Collections.Generic.List[string]'
        CancelRequest = $false
    }
}

function Initialize-RedimoEnvironment {
    [CmdletBinding()]
    param(
        [string]$DataRoot,
        [switch]$DryRun,
        [hashtable]$SyncHash
    )

    if ($DataRoot) {
        $script:Redimo.DataRoot   = $DataRoot
        $script:Redimo.LogsDir    = Join-Path $DataRoot 'logs'
        $script:Redimo.BackupsDir = Join-Path $DataRoot 'backups'
        $script:Redimo.StateFile  = Join-Path $DataRoot 'state.json'
    }

    if ($PSBoundParameters.ContainsKey('DryRun')) {
        $script:Redimo.DryRun = [bool]$DryRun
    }

    if ($SyncHash) {
        $script:Redimo.SyncHash = $SyncHash
    }

    try {
        if (-not (Test-Path -LiteralPath $script:Redimo.LogsDir)) {
            New-Item -Path $script:Redimo.LogsDir -ItemType Directory -Force | Out-Null
        }
        if (-not (Test-Path -LiteralPath $script:Redimo.BackupsDir)) {
            New-Item -Path $script:Redimo.BackupsDir -ItemType Directory -Force | Out-Null
        }
    }
    catch {
        $fallbackRoot = Join-Path $env:TEMP 'redimo'
        $script:Redimo.DataRoot   = $fallbackRoot
        $script:Redimo.LogsDir    = Join-Path $fallbackRoot 'logs'
        $script:Redimo.BackupsDir = Join-Path $fallbackRoot 'backups'
        $script:Redimo.StateFile  = Join-Path $fallbackRoot 'state.json'
        New-Item -Path $script:Redimo.LogsDir -ItemType Directory -Force | Out-Null
        New-Item -Path $script:Redimo.BackupsDir -ItemType Directory -Force | Out-Null
    }

    if (-not $script:Redimo.SessionId) {
        $script:Redimo.SessionId = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'
    }
    $script:Redimo.LogFile = Join-Path $script:Redimo.LogsDir ("redimo_{0}.log" -f $script:Redimo.SessionId)
    return $script:Redimo
}

function Write-OptimizerLog {
    [CmdletBinding()]
    param(
        [ValidateSet('INFO', 'OK', 'WARN', 'ERROR', 'DRYRUN')]
        [string]$Level = 'INFO',

        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Message
    )

    $timestamp = Get-Date -Format 'HH:mm:ss'
    $line = "[{0}] [{1}] {2}" -f $timestamp, $Level, $Message

    if ($script:Redimo -and $null -ne $script:Redimo.LogHistory) {
        [void]$script:Redimo.LogHistory.Add($line)
    }

    if ($script:Redimo -and $script:Redimo.LogFile) {
        try {
            $utf8Bom = New-Object System.Text.UTF8Encoding($true)
            [System.IO.File]::AppendAllText($script:Redimo.LogFile, ($line + [Environment]::NewLine), $utf8Bom)
        }
        catch {
            Write-Verbose ("Falha ao gravar arquivo de log: {0}" -f $_.Exception.Message)
        }
    }

    if ($script:Redimo -and $script:Redimo.SyncHash) {
        $sync = $script:Redimo.SyncHash
        if ($sync.LogQueue) {
            $entry = [pscustomobject]@{
                Timestamp = $timestamp
                Level     = $Level
                Message   = $Message
                Formatted = $line
            }
            $sync.LogQueue.Enqueue($entry)
        }
        $sync.StatusText = $Message
    }
}

function Invoke-Mutation {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Description,

        [Parameter(Mandatory = $true)]
        [scriptblock]$Action
    )

    if ($script:Redimo -and $script:Redimo.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message $Description
        return $true
    }

    try {
        & $Action
        Write-OptimizerLog -Level OK -Message $Description
        return $true
    }
    catch {
        Write-OptimizerLog -Level WARN -Message ("{0} $([char]0x2014) {1}" -f $Description, $_.Exception.Message)
        throw
    }
}

# ============================================================================
# Module: src/windows/core/backup.ps1
# ============================================================================
# Ponto de Restaura--o, exporta--o de chaves (.reg) e persist-ncia at-mica de Undo (state.json)

function New-RedimoBackupSession {
    [CmdletBinding()]
    param(
        [string]$SessionId
    )

    if (-not $script:Redimo) {
        Initialize-RedimoEnvironment | Out-Null
    }

    if ($SessionId) {
        $script:Redimo.SessionId = $SessionId
    }
    elseif (-not $script:Redimo.SessionId) {
        $script:Redimo.SessionId = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'
    }

    $sessionDir = Join-Path $script:Redimo.BackupsDir $script:Redimo.SessionId
    if (-not $script:Redimo.DryRun) {
        if (-not (Test-Path -LiteralPath $sessionDir)) {
            New-Item -Path $sessionDir -ItemType Directory -Force | Out-Null
        }
    }
    else {
        Write-OptimizerLog -Level DRYRUN -Message ("Criar diret$([char]0x00F3)rio de sess$([char]0x00E3)o de backup: {0}" -f $sessionDir)
    }

    $script:Redimo.SessionDir = $sessionDir
    return $sessionDir
}

function ConvertTo-RegExePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$PsPath
    )

    $clean = $PsPath.Trim()
    $clean = $clean -replace '^Microsoft\.PowerShell\.Core\\Registry::', ''
    $clean = $clean -replace '^HKEY_LOCAL_MACHINE\\', 'HKLM\'
    $clean = $clean -replace '^HKEY_CURRENT_USER\\', 'HKCU\'
    $clean = $clean -replace '^HKEY_CLASSES_ROOT\\', 'HKCR\'
    $clean = $clean -replace '^HKEY_USERS\\', 'HKU\'
    $clean = $clean -replace '^HKLM:\\?', 'HKLM\'
    $clean = $clean -replace '^HKCU:\\?', 'HKCU\'
    $clean = $clean -replace '^HKCR:\\?', 'HKCR\'
    $clean = $clean -replace '^HKU:\\?', 'HKU\'
    return $clean
}

function Export-RegistryKeyBackup {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyCollection()]
        [string[]]$Paths,

        [string]$DestinationDir
    )

    if (-not $Paths -or $Paths.Count -eq 0) {
        return @()
    }

    if (-not $DestinationDir) {
        if (-not $script:Redimo.SessionDir) {
            New-RedimoBackupSession | Out-Null
        }
        $DestinationDir = $script:Redimo.SessionDir
    }

    $exportedFiles = New-Object 'System.Collections.Generic.List[string]'
    $uniquePaths = $Paths | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique

    foreach ($psPath in $uniquePaths) {
        $regPath = ConvertTo-RegExePath -PsPath $psPath
        $safeName = ($regPath -replace '[\\/:*?"<>|\s\{\}]', '_') + '.reg'
        $outFile = Join-Path $DestinationDir $safeName

        if ($script:Redimo -and $script:Redimo.DryRun) {
            Write-OptimizerLog -Level DRYRUN -Message ("Exportar chave de registro '{0}' para '{1}'" -f $regPath, $outFile)
            [void]$exportedFiles.Add($outFile)
            continue
        }

        if (-not (Test-Path -LiteralPath $psPath)) {
            Write-OptimizerLog -Level INFO -Message ("Chave '{0}' ainda n$([char]0x00E3)o existe no sistema (sem necessidade de export .reg)." -f $psPath)
            continue
        }

        try {
            if (-not (Test-Path -LiteralPath $DestinationDir)) {
                New-Item -Path $DestinationDir -ItemType Directory -Force | Out-Null
            }
            $proc = Start-Process -FilePath 'reg.exe' -ArgumentList @('export', $regPath, $outFile, '/y') -NoNewWindow -Wait -PassThru
            if ($proc.ExitCode -eq 0 -and (Test-Path -LiteralPath $outFile)) {
                Write-OptimizerLog -Level OK -Message ("Backup de registro salvo: {0}" -f $safeName)
                [void]$exportedFiles.Add($outFile)
            }
            else {
                Write-OptimizerLog -Level WARN -Message ("reg.exe export retornou c$([char]0x00F3)digo {0} para '{1}'" -f $proc.ExitCode, $regPath)
            }
        }
        catch {
            Write-OptimizerLog -Level WARN -Message ("Falha ao exportar '{0}': {1}" -f $regPath, $_.Exception.Message)
        }
    }

    return $exportedFiles.ToArray()
}

function Read-RedimoStateFile {
    [CmdletBinding()]
    param(
        [string]$StateFilePath
    )

    if (-not $StateFilePath) {
        $StateFilePath = $script:Redimo.StateFile
    }

    $result = @{}
    if (-not $StateFilePath -or -not (Test-Path -LiteralPath $StateFilePath)) {
        return $result
    }

    try {
        $raw = [System.IO.File]::ReadAllText($StateFilePath, [System.Text.Encoding]::UTF8)
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return $result
        }
        $parsed = $raw | ConvertFrom-Json
        if ($null -ne $parsed) {
            foreach ($prop in $parsed.PSObject.Properties) {
                $result[$prop.Name] = $prop.Value
            }
        }
    }
    catch {
        Write-OptimizerLog -Level WARN -Message ("N$([char]0x00E3)o foi poss$([char]0x00ED)vel ler state.json em '{0}': {1}" -f $StateFilePath, $_.Exception.Message)
    }

    return $result
}

function Write-RedimoStateFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$StateData,

        [string]$StateFilePath
    )

    if (-not $StateFilePath) {
        $StateFilePath = $script:Redimo.StateFile
    }

    if ($script:Redimo -and $script:Redimo.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Atualizar arquivo de estado '{0}' ({1} entradas)" -f $StateFilePath, $StateData.Count)
        return
    }

    $parentDir = Split-Path -Path $StateFilePath -Parent
    if ($parentDir -and -not (Test-Path -LiteralPath $parentDir)) {
        New-Item -Path $parentDir -ItemType Directory -Force | Out-Null
    }

    $tmpFile = "{0}.{1}.tmp" -f $StateFilePath, [Guid]::NewGuid().ToString('N')
    $utf8Bom = New-Object System.Text.UTF8Encoding($true)
    $json = [pscustomobject]$StateData | ConvertTo-Json -Depth 10

    try {
        [System.IO.File]::WriteAllText($tmpFile, $json, $utf8Bom)
        if (Test-Path -LiteralPath $StateFilePath) {
            Remove-Item -LiteralPath $StateFilePath -Force
        }
        Move-Item -LiteralPath $tmpFile -Destination $StateFilePath -Force

        if ($script:Redimo -and $script:Redimo.SessionDir -and (Test-Path -LiteralPath $script:Redimo.SessionDir)) {
            $snapshotPath = Join-Path $script:Redimo.SessionDir 'state-snapshot.json'
            [System.IO.File]::WriteAllText($snapshotPath, $json, $utf8Bom)
        }
    }
    catch {
        if (Test-Path -LiteralPath $tmpFile) {
            Remove-Item -LiteralPath $tmpFile -Force -ErrorAction SilentlyContinue
        }
        Write-OptimizerLog -Level WARN -Message ("Falha na escrita at$([char]0x00F4)mica do state.json: {0}" -f $_.Exception.Message)
        throw
    }
}

function Save-CapturedState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Id,

        [Parameter(Mandatory = $true)]
        [AllowEmptyCollection()]
        [array]$CapturedItems,

        [switch]$ForceOverwrite,
        [string]$StateFilePath
    )

    if ($script:Redimo -and $script:Redimo.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Capturar estado original para '{0}' ({1} itens)" -f $Id, $CapturedItems.Count)
        return
    }

    $state = Read-RedimoStateFile -StateFilePath $StateFilePath
    if ($state.ContainsKey($Id) -and -not $ForceOverwrite) {
        Write-OptimizerLog -Level INFO -Message ("Estado original de '{0}' j$([char]0x00E1) est$([char]0x00E1) preservado no state.json (first-capture-wins)." -f $Id)
        return
    }

    $state[$Id] = [pscustomobject]@{
        appliedAt = (Get-Date -Format 'o')
        session   = if ($script:Redimo -and $script:Redimo.SessionId) { $script:Redimo.SessionId } else { (Get-Date -Format 'yyyy-MM-dd_HH-mm-ss') }
        captured  = @($CapturedItems)
    }

    Write-RedimoStateFile -StateData $state -StateFilePath $StateFilePath
}

function Get-CapturedState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Id,

        [string]$StateFilePath
    )

    $state = Read-RedimoStateFile -StateFilePath $StateFilePath
    if ($state.ContainsKey($Id)) {
        return $state[$Id]
    }
    return $null
}

function Remove-CapturedState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Id,

        [string]$StateFilePath
    )

    if ($script:Redimo -and $script:Redimo.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Remover entrada '{0}' do state.json ap$([char]0x00F3)s Undo" -f $Id)
        return
    }

    $state = Read-RedimoStateFile -StateFilePath $StateFilePath
    if ($state.ContainsKey($Id)) {
        [void]$state.Remove($Id)
        Write-RedimoStateFile -StateData $state -StateFilePath $StateFilePath
    }
}

function New-RedimoRestorePoint {
    [CmdletBinding()]
    param(
        [string]$Description = "redimo - Antes de aplicar otimiza$([char]0x00E7)$([char]0x00F5)es",
        [scriptblock]$ConfirmEnableProtection
    )

    if ($script:Redimo -and $script:Redimo.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Criar Ponto de Restaura$([char]0x00E7)$([char]0x00E3)o do Sistema: '{0}'" -f $Description)
        return $true
    }

    $srKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore'
    $hadFreqValue = $false
    $prevFreqValue = $null

    try {
        $rpInterval = 0
        if (Test-Path -LiteralPath $srKey) {
            $srProps = Get-ItemProperty -LiteralPath $srKey -ErrorAction SilentlyContinue
            if ($null -ne $srProps -and $null -ne $srProps.RPSessionInterval) {
                $rpInterval = [int]$srProps.RPSessionInterval
            }
            if ($null -ne $srProps -and ($srProps.PSObject.Properties.Name -contains 'SystemRestorePointCreationFrequency')) {
                $hadFreqValue = $true
                $prevFreqValue = $srProps.SystemRestorePointCreationFrequency
            }
        }

        if ($rpInterval -eq 0) {
            $shouldEnable = $false
            if ($ConfirmEnableProtection) {
                $shouldEnable = [bool](& $ConfirmEnableProtection)
            }
            if ($shouldEnable) {
                Write-OptimizerLog -Level INFO -Message "Ativando Prote$([char]0x00E7)$([char]0x00E3)o do Sistema na unidade C:\..."
                Enable-ComputerRestore -Drive 'C:\' -ErrorAction Stop
            }
            else {
                Write-OptimizerLog -Level WARN -Message "Prote$([char]0x00E7)$([char]0x00E3)o do Sistema desativada em C:\. Seguindo com backup .reg e state.json."
                return $false
            }
        }

        if (-not (Test-Path -LiteralPath $srKey)) {
            New-Item -Path $srKey -Force | Out-Null
        }
        Set-ItemProperty -LiteralPath $srKey -Name 'SystemRestorePointCreationFrequency' -Value 0 -Type DWord -ErrorAction Stop

        Write-OptimizerLog -Level INFO -Message ("Criando Ponto de Restaura$([char]0x00E7)$([char]0x00E3)o: '{0}'..." -f $Description)
        Checkpoint-Computer -Description $Description -RestorePointType 'MODIFY_SETTINGS' -ErrorAction Stop
        Write-OptimizerLog -Level OK -Message "Ponto de Restaura$([char]0x00E7)$([char]0x00E3)o do Sistema criado com sucesso."
        return $true
    }
    catch {
        Write-OptimizerLog -Level WARN -Message ("N$([char]0x00E3)o foi poss$([char]0x00ED)vel criar Ponto de Restaura$([char]0x00E7)$([char]0x00E3)o ({0}). Os backups .reg e state.json continuam ativos." -f $_.Exception.Message)
        return $false
    }
    finally {
        try {
            if (Test-Path -LiteralPath $srKey) {
                if ($hadFreqValue) {
                    Set-ItemProperty -LiteralPath $srKey -Name 'SystemRestorePointCreationFrequency' -Value $prevFreqValue -Type DWord -ErrorAction SilentlyContinue
                }
                else {
                    Remove-ItemProperty -LiteralPath $srKey -Name 'SystemRestorePointCreationFrequency' -ErrorAction SilentlyContinue
                }
            }
        }
        catch {
            Write-Verbose ("Erro ao restaurar SystemRestorePointCreationFrequency: {0}" -f $_.Exception.Message)
        }
    }
}

# ============================================================================
# Module: src/windows/modules/hardware-utils.ps1
# ============================================================================
# Detec--o de Hardware (CPU/GPU/Chassi/SSD/Build) e Otimiza--es de Energia e Portas USB

function Get-RedimoHardware {
    [CmdletBinding()]
    param(
        [switch]$Force
    )

    if ($script:RedimoHardwareCache -and -not $Force) {
        return $script:RedimoHardwareCache
    }

    $cpuName = 'CPU Desconhecida'
    try {
        $regCpu = Get-ItemProperty -LiteralPath 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' -Name 'ProcessorNameString' -ErrorAction SilentlyContinue
        if ($regCpu -and $regCpu.ProcessorNameString) {
            $cpuName = $regCpu.ProcessorNameString.Trim()
        }
    }
    catch {
        Write-Verbose ("Falha ao ler nome da CPU do registro: {0}" -f $_.Exception.Message)
    }

    $isX3D = [bool]($cpuName -match '(?i)\b\d{4}X3D\b')

    $isLaptop = $false
    try {
        $enclosure = Get-CimInstance -ClassName Win32_SystemEnclosure -ErrorAction SilentlyContinue
        $laptopChassis = @(8, 9, 10, 11, 12, 14, 18, 21, 30, 31, 32)
        if ($enclosure -and $enclosure.ChassisTypes) {
            foreach ($ct in $enclosure.ChassisTypes) {
                if ($laptopChassis -contains [int]$ct) {
                    $isLaptop = $true
                    break
                }
            }
        }
        if (-not $isLaptop) {
            $battery = Get-CimInstance -ClassName Win32_Battery -ErrorAction SilentlyContinue
            if ($battery) {
                $isLaptop = $true
            }
        }
    }
    catch {
        Write-Verbose ("Falha ao detectar chassi/bateria via CIM: {0}" -f $_.Exception.Message)
    }

    $gpuNames = New-Object 'System.Collections.Generic.List[string]'
    $gpuVendors = New-Object 'System.Collections.Generic.List[string]'
    try {
        $gpus = Get-CimInstance -ClassName Win32_VideoController -ErrorAction SilentlyContinue
        foreach ($g in $gpus) {
            if ($g.Name) {
                [void]$gpuNames.Add($g.Name.Trim())
                if ($g.Name -match '(?i)NVIDIA|GeForce|RTX|GTX') {
                    if (-not $gpuVendors.Contains('NVIDIA')) { [void]$gpuVendors.Add('NVIDIA') }
                }
                elseif ($g.Name -match '(?i)AMD|Radeon|RX\s') {
                    if (-not $gpuVendors.Contains('AMD')) { [void]$gpuVendors.Add('AMD') }
                }
                elseif ($g.Name -match '(?i)Intel|Arc|Iris|UHD') {
                    if (-not $gpuVendors.Contains('Intel')) { [void]$gpuVendors.Add('Intel') }
                }
            }
        }
    }
    catch {
        Write-Verbose ("Falha ao detectar GPUs via CIM: {0}" -f $_.Exception.Message)
    }

    $isSsd = $true
    try {
        if (Get-Command Get-PhysicalDisk -ErrorAction SilentlyContinue) {
            $disks = Get-PhysicalDisk -ErrorAction SilentlyContinue
            if ($disks) {
                $hddOnly = ($disks | Where-Object { $_.MediaType -eq 'SSD' }).Count -eq 0 -and ($disks | Where-Object { $_.MediaType -eq 'HDD' }).Count -gt 0
                if ($hddOnly) { $isSsd = $false }
            }
        }
    }
    catch {
        Write-Verbose ("Falha ao detectar tipo de disco: {0}" -f $_.Exception.Message)
    }

    $osBuild = [int][Environment]::OSVersion.Version.Build
    $isWin11 = ($osBuild -ge 22000)
    $osLabel = if ($isWin11) { "Windows 11 (Build $osBuild)" } else { "Windows 10 (Build $osBuild)" }
    $chassisLabel = if ($isLaptop) { 'Notebook' } else { 'Desktop' }
    $gpuPrimary = if ($gpuNames.Count -gt 0) { $gpuNames[0] } else { "GPU Padr$([char]0x00E3)o" }

    $script:RedimoHardwareCache = [pscustomobject]@{
        CpuName         = $cpuName
        IsX3D           = $isX3D
        IsLaptop        = $isLaptop
        GpuNames        = $gpuNames.ToArray()
        GpuVendors      = $gpuVendors.ToArray()
        SystemDiskIsSSD = $isSsd
        OsBuild         = $osBuild
        IsWin11         = $isWin11
        Summary         = "$cpuName | $gpuPrimary | $chassisLabel | $osLabel"
    }

    return $script:RedimoHardwareCache
}

function Get-ActivePowerPlanGuid {
    [CmdletBinding()]
    param()

    try {
        $out = & powercfg.exe /getactivescheme 2>$null | Out-String
        if ($out -match '([0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12})') {
            return $Matches[1].ToLowerInvariant()
        }
    }
    catch {
        Write-Verbose ("Erro ao obter plano de energia ativo: {0}" -f $_.Exception.Message)
    }
    return '381b4222-f694-41f0-9685-ff5bb260df2e'
}

function Set-RedimoSmartPowerPlan {
    [CmdletBinding()]
    param()

    $hw = Get-RedimoHardware
    $currentGuid = Get-ActivePowerPlanGuid
    Save-CapturedState -Id 'PowerPlanOriginal' -CapturedItems @(
        @{ kind = 'powerplan'; guid = $currentGuid }
    )

    $balancedGuid = '381b4222-f694-41f0-9685-ff5bb260df2e'
    $highPerfGuid = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'

    if ($hw.IsLaptop) {
        Write-OptimizerLog -Level INFO -Message "Notebook detectado: mantendo plano Equilibrado (Balanced) para preservar autonomia e gerenciamento t$([char]0x00E9)rmico."
        Invoke-Mutation -Description 'Ativar plano Equilibrado (Balanced) para Notebook' -Action {
            & powercfg.exe /setactive $balancedGuid | Out-Null
        } | Out-Null
        return
    }

    if ($hw.IsX3D) {
        Write-OptimizerLog -Level INFO -Message ("CPU AMD Ryzen X3D detectada ({0}): recomendando e ativando plano Equilibrado (exigido pelo Core Parking do 3D V-Cache)." -f $hw.CpuName)
        Invoke-Mutation -Description 'Ativar plano Equilibrado para AMD Ryzen X3D' -Action {
            & powercfg.exe /setactive $balancedGuid | Out-Null
        } | Out-Null
        return
    }

    Invoke-Mutation -Description 'Ativar plano de energia Alto Desempenho (Desktop)' -Action {
        & powercfg.exe /setactive $highPerfGuid | Out-Null
    } | Out-Null
}

function Enable-RedimoUltimatePowerPlan {
    [CmdletBinding()]
    param()

    $currentGuid = Get-ActivePowerPlanGuid
    Save-CapturedState -Id 'PowerPlanOriginal' -CapturedItems @(
        @{ kind = 'powerplan'; guid = $currentGuid }
    )

    $ultimateTemplate = 'e9a42b02-d5df-448d-aa00-03f14749eb61'
    Invoke-Mutation -Description 'Desbloquear e ativar plano Ultimate Performance (sem duplicar)' -Action {
        $listOut = & powercfg.exe /list 2>$null | Out-String
        $targetGuid = $null

        foreach ($line in ($listOut -split "\r?\n")) {
            if ($line -match '(?i)(e9a42b02-d5df-448d-aa00-03f14749eb61|Ultimate Performance|Desempenho M.ximo)' -and
                $line -match '([0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12})') {
                $targetGuid = $Matches[1].ToLowerInvariant()
                break
            }
        }

        if (-not $targetGuid) {
            $dupOut = & powercfg.exe -duplicatescheme $ultimateTemplate 2>$null | Out-String
            if ($dupOut -match '([0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12})') {
                $targetGuid = $Matches[1].ToLowerInvariant()
            }
            else {
                $targetGuid = $ultimateTemplate
            }
        }

        & powercfg.exe /setactive $targetGuid | Out-Null
    } | Out-Null
}

