function Test-AntiCheatGuardrail {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Id,

        [Parameter(Mandatory = $true)]
        [pscustomobject]$Tweak
    )

    foreach ($svc in @($Tweak.services)) {
        if ($svc.name -match '^(?i)(vgc|vgk|BEService|EasyAntiCheat|FACEITService)$') {
            $msg = "GUARDRAIL ANTI-CHEAT: O tweak '$Id' tentou modificar o servi$([char]0x00E7)o protegido de anti-cheat '$($svc.name)'. Opera$([char]0x00E7)$([char]0x00E3)o abortada."
            Write-OptimizerLog -Level ERROR -Message $msg
            throw $msg
        }
    }

    foreach ($reg in @($Tweak.registry)) {
        if ($reg.name -match '^(?i)EnableVirtualizationBasedSecurity$' -or
            $reg.path -match '(?i)\\Services\\(vgc|vgk|TPM)\b' -or
            $reg.path -match '(?i)\\SecureBoot\\State\b') {
            $msg = "GUARDRAIL ANTI-CHEAT: O tweak '$Id' tentou modificar chave cr$([char]0x00ED)tica de seguran$([char]0x00E7)a/anti-cheat ('$($reg.path)\$($reg.name)'). Opera$([char]0x00E7)$([char]0x00E3)o abortada."
            Write-OptimizerLog -Level ERROR -Message $msg
            throw $msg
        }
    }

    foreach ($apx in @($Tweak.appx)) {
        if ($script:ProtectedAppxPackages -contains $apx.name) {
            $msg = "GUARDRAIL DE SISTEMA: O tweak '$Id' tentou remover o pacote essencial protegido '$($apx.name)'. Opera$([char]0x00E7)$([char]0x00E3)o abortada."
            Write-OptimizerLog -Level ERROR -Message $msg
            throw $msg
        }
    }
}

function Get-RegistryEntryState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [string]$Name,

        [string]$FallbackType = 'DWord'
    )

    if (-not (Test-Path -LiteralPath $Path)) {
        return [pscustomobject]@{
            KeyExisted   = $false
            ValueExisted = $false
            Value        = $null
            Type         = $FallbackType
        }
    }

    try {
        $item = Get-Item -LiteralPath $Path -ErrorAction Stop
        $lookupName = if ($Name -eq '(Default)') { '' } else { $Name }
        $valNames = @($item.GetValueNames())
        $valExisted = ($valNames -contains $lookupName)

        if (-not $valExisted) {
            return [pscustomobject]@{
                KeyExisted   = $true
                ValueExisted = $false
                Value        = $null
                Type         = $FallbackType
            }
        }

        $rawVal = $item.GetValue($lookupName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
        $kind = $FallbackType
        try {
            $kind = $item.GetValueKind($lookupName).ToString()
        }
        catch {
            $kind = $FallbackType
        }

        return [pscustomobject]@{
            KeyExisted   = $true
            ValueExisted = $true
            Value        = $rawVal
            Type         = $kind
        }
    }
    catch {
        return [pscustomobject]@{
            KeyExisted   = $false
            ValueExisted = $false
            Value        = $null
            Type         = $FallbackType
        }
    }
}

function Set-RegistryEntryValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [string]$Name,

        [string]$Type = 'DWord',

        [Parameter(Mandatory = $true)]
        [AllowNull()]
        [AllowEmptyString()]
        $Value
    )

    if ($Value -is [string] -and $Value -eq '<RemoveKey>') {
        Invoke-Mutation -Description ("Remover chave de registro '{0}'" -f $Path) -Action {
            if (Test-Path -LiteralPath $Path) {
                Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop
            }
        } | Out-Null
        return
    }

    if ($Value -is [string] -and $Value -eq '<RemoveEntry>') {
        Invoke-Mutation -Description ("Remover valor de registro '{0}\{1}'" -f $Path, $Name) -Action {
            if (Test-Path -LiteralPath $Path) {
                if ($Name -eq '(Default)') {
                    $regItem = Get-Item -LiteralPath $Path -ErrorAction SilentlyContinue
                    if ($regItem -and (@($regItem.GetValueNames()) -contains '')) {
                        Remove-ItemProperty -LiteralPath $Path -Name '(Default)' -Force -ErrorAction SilentlyContinue
                    }
                }
                else {
                    $prop = Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction SilentlyContinue
                    if ($null -ne $prop) {
                        Remove-ItemProperty -LiteralPath $Path -Name $Name -Force -ErrorAction Stop
                    }
                }
            }
        } | Out-Null
        return
    }

    Invoke-Mutation -Description ("Definir registro '{0}\{1}' = '{2}' ({3})" -f $Path, $Name, $Value, $Type) -Action {
        if (-not (Test-Path -LiteralPath $Path)) {
            New-Item -Path $Path -Force -ErrorAction Stop | Out-Null
        }

        if ($Name -eq '(Default)') {
            Set-Item -LiteralPath $Path -Value ([string]$Value) -ErrorAction Stop
        }
        else {
            $castValue = switch ($Type) {
                'DWord'  { [int]$Value }
                'QWord'  { [long]$Value }
                'String' { [string]$Value }
                'ExpandString' { [string]$Value }
                default  { $Value }
            }
            Set-ItemProperty -LiteralPath $Path -Name $Name -Value $castValue -Type $Type -Force -ErrorAction Stop
        }
    } | Out-Null
}

function Set-ServiceStartupState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$ServiceName,

        [Parameter(Mandatory = $true)]
        [string]$StartupType
    )

    Invoke-Mutation -Description ("Configurar servi$([char]0x00E7)o '{0}' para '{1}'" -f $ServiceName, $StartupType) -Action {
        $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
        if (-not $svc) {
            Write-OptimizerLog -Level INFO -Message ("Servi$([char]0x00E7)o '{0}' n$([char]0x00E3)o est$([char]0x00E1) presente nesta edi$([char]0x00E7)$([char]0x00E3)o do Windows (ignorado)." -f $ServiceName)
            return
        }

        if ($StartupType -eq 'AutomaticDelayedStart') {
            Start-Process -FilePath 'sc.exe' -ArgumentList @('config', $ServiceName, 'start=', 'delayed-auto') -NoNewWindow -Wait | Out-Null
        }
        else {
            Set-Service -Name $ServiceName -StartupType $StartupType -ErrorAction Stop
        }

        if ($StartupType -eq 'Disabled' -and $svc.Status -eq 'Running') {
            Stop-Service -Name $ServiceName -Force -ErrorAction SilentlyContinue
        }
    } | Out-Null
}

function Set-ScheduledTaskState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$TaskPath,

        [Parameter(Mandatory = $true)]
        [string]$TaskName,

        [Parameter(Mandatory = $true)]
        [string]$DesiredState
    )

    Invoke-Mutation -Description ("Configurar tarefa agendada '{0}{1}' para '{2}'" -f $TaskPath, $TaskName, $DesiredState) -Action {
        $task = Get-ScheduledTask -TaskPath $TaskPath -TaskName $TaskName -ErrorAction SilentlyContinue
        if (-not $task) {
            Write-OptimizerLog -Level INFO -Message ("Tarefa agendada '{0}{1}' n$([char]0x00E3)o existe neste sistema (ignorada)." -f $TaskPath, $TaskName)
            return
        }

        if ($DesiredState -eq 'Disabled') {
            Disable-ScheduledTask -TaskPath $TaskPath -TaskName $TaskName -ErrorAction Stop | Out-Null
        }
        else {
            Enable-ScheduledTask -TaskPath $TaskPath -TaskName $TaskName -ErrorAction Stop | Out-Null
        }
    } | Out-Null
}

function Invoke-AppxRemoval {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$PackageName,

        [Parameter(Mandatory = $true)]
        [string]$StoreId,

        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    if ($script:ProtectedAppxPackages -contains $PackageName) {
        throw "Pacote Appx '$PackageName' $([char]0x00E9) protegido e n$([char]0x00E3)o pode ser removido."
    }

    if ($Mode -eq 'Apply') {
        Invoke-Mutation -Description ("Remover pacote Appx '{0}' (usu$([char]0x00E1)rios + provisionamento)" -f $PackageName) -Action {
            $pkgs = Get-AppxPackage -AllUsers -Name "*$PackageName*" -ErrorAction SilentlyContinue
            foreach ($p in $pkgs) {
                Remove-AppxPackage -Package $p.PackageFullName -AllUsers -ErrorAction SilentlyContinue
            }
            $prov = Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue |
                Where-Object { $_.DisplayName -like "*$PackageName*" }
            foreach ($pr in $prov) {
                Remove-AppxProvisionedPackage -Online -PackageName $pr.PackageName -ErrorAction SilentlyContinue | Out-Null
            }
        } | Out-Null
    }
    else {
        Invoke-Mutation -Description ("Reinstalar pacote Appx '{0}' (Store ID: {1}) via Winget" -f $PackageName, $StoreId) -Action {
            $wg = Test-WingetAvailable
            if ($wg.Available) {
                $argsList = @('install', '--id', $StoreId, '--source', 'msstore', '--exact', '--silent', '--accept-package-agreements', '--accept-source-agreements')
                Start-Process -FilePath $wg.Path -ArgumentList $argsList -NoNewWindow -Wait | Out-Null
            }
            else {
                Write-OptimizerLog -Level WARN -Message ("Winget indispon$([char]0x00ED)vel para reinstalar '{0}' ({1})." -f $PackageName, $StoreId)
            }
        } | Out-Null
    }
}

function Invoke-TweakHelperScript {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$FunctionName
    )

    if ($script:AllowedTweakScripts -notcontains $FunctionName) {
        $msg = "Fun$([char]0x00E7)$([char]0x00E3)o helper '$FunctionName' n$([char]0x00E3)o consta na whitelist de seguran$([char]0x00E7)a do tweak-engine."
        Write-OptimizerLog -Level ERROR -Message $msg
        throw $msg
    }

    & $FunctionName
}

function Invoke-Tweak {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Id,

        [Parameter(Mandatory = $true)]
        [pscustomobject]$Tweak,

        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    Test-AntiCheatGuardrail -Id $Id -Tweak $Tweak

    if ($Mode -eq 'Apply') {
        Write-OptimizerLog -Level INFO -Message ("Aplicando tweak: {0} ({1})" -f $Tweak.title, $Id)

        $capturedItems = New-Object 'System.Collections.Generic.List[hashtable]'
        $regPathsToBackup = New-Object 'System.Collections.Generic.List[string]'

        foreach ($reg in @($Tweak.registry)) {
            $state = Get-RegistryEntryState -Path $reg.path -Name $reg.name -FallbackType $reg.type
            [void]$capturedItems.Add(@{
                kind            = 'registry'
                path            = $reg.path
                name            = $reg.name
                keyExisted      = [bool]$state.KeyExisted
                existed         = [bool]$state.ValueExisted
                type            = $state.Type
                value           = $state.Value
                isRemoveKeyHint = ($reg.originalValue -eq '<RemoveKey>')
            })
            if ($state.KeyExisted) {
                [void]$regPathsToBackup.Add($reg.path)
            }
        }

        foreach ($svc in @($Tweak.services)) {
            $svcObj = Get-Service -Name $svc.name -ErrorAction SilentlyContinue
            [void]$capturedItems.Add(@{
                kind        = 'service'
                name        = $svc.name
                existed     = ($null -ne $svcObj)
                startupType = if ($svcObj) { $svcObj.StartType.ToString() } else { $svc.originalType }
            })
        }

        foreach ($tsk in @($Tweak.scheduledTasks)) {
            $tskObj = Get-ScheduledTask -TaskPath $tsk.path -TaskName $tsk.name -ErrorAction SilentlyContinue
            [void]$capturedItems.Add(@{
                kind    = 'scheduledTask'
                path    = $tsk.path
                name    = $tsk.name
                existed = ($null -ne $tskObj)
                state   = if ($tskObj) { $tskObj.State.ToString() } else { $tsk.originalState }
            })
        }

        foreach ($apx in @($Tweak.appx)) {
            $pkgObj = Get-AppxPackage -Name "*$($apx.name)*" -ErrorAction SilentlyContinue
            [void]$capturedItems.Add(@{
                kind    = 'appx'
                name    = $apx.name
                storeId = $apx.storeId
                existed = ($null -ne $pkgObj)
            })
        }

        Save-CapturedState -Id $Id -CapturedItems $capturedItems.ToArray()
        if ($regPathsToBackup.Count -gt 0) {
            Export-RegistryKeyBackup -Paths $regPathsToBackup.ToArray() | Out-Null
        }

        foreach ($reg in @($Tweak.registry)) {
            Set-RegistryEntryValue -Path $reg.path -Name $reg.name -Type $reg.type -Value $reg.value
        }

        foreach ($svc in @($Tweak.services)) {
            Set-ServiceStartupState -ServiceName $svc.name -StartupType $svc.startupType
        }

        foreach ($tsk in @($Tweak.scheduledTasks)) {
            Set-ScheduledTaskState -TaskPath $tsk.path -TaskName $tsk.name -DesiredState $tsk.state
        }

        foreach ($apx in @($Tweak.appx)) {
            Invoke-AppxRemoval -PackageName $apx.name -StoreId $apx.storeId -Mode 'Apply'
        }

        foreach ($fn in @($Tweak.invokeScript)) {
            if (-not [string]::IsNullOrWhiteSpace($fn)) {
                Invoke-TweakHelperScript -FunctionName $fn
            }
        }

        return $true
    }
    else {
        Write-OptimizerLog -Level INFO -Message ("Revertendo tweak (Undo): {0} ({1})" -f $Tweak.title, $Id)
        $capturedRecord = Get-CapturedState -Id $Id
        $capturedList = if ($capturedRecord -and $capturedRecord.captured) { @($capturedRecord.captured) } else { @() }

        foreach ($fn in @($Tweak.undoScript)) {
            if (-not [string]::IsNullOrWhiteSpace($fn)) {
                Invoke-TweakHelperScript -FunctionName $fn
            }
        }

        foreach ($apx in @($Tweak.appx)) {
            Invoke-AppxRemoval -PackageName $apx.name -StoreId $apx.storeId -Mode 'Undo'
        }

        foreach ($tsk in @($Tweak.scheduledTasks)) {
            $capTask = $capturedList | Where-Object { $_.kind -eq 'scheduledTask' -and $_.path -eq $tsk.path -and $_.name -eq $tsk.name } | Select-Object -First 1
            $targetState = if ($capTask -and $capTask.existed -and $capTask.state) { $capTask.state } else { $tsk.originalState }
            Set-ScheduledTaskState -TaskPath $tsk.path -TaskName $tsk.name -DesiredState $targetState
        }

        foreach ($svc in @($Tweak.services)) {
            $capSvc = $capturedList | Where-Object { $_.kind -eq 'service' -and $_.name -eq $svc.name } | Select-Object -First 1
            $targetType = if ($capSvc -and $capSvc.existed -and $capSvc.startupType) { $capSvc.startupType } else { $svc.originalType }
            Set-ServiceStartupState -ServiceName $svc.name -StartupType $targetType
        }

        $regArray = @($Tweak.registry)
        for ($i = $regArray.Count - 1; $i -ge 0; $i--) {
            $reg = $regArray[$i]
            $capReg = $capturedList | Where-Object { $_.kind -eq 'registry' -and $_.path -eq $reg.path -and $_.name -eq $reg.name } | Select-Object -First 1

            if ($null -ne $capReg) {
                if (($capReg.isRemoveKeyHint -or $reg.originalValue -eq '<RemoveKey>') -and (-not $capReg.keyExisted)) {
                    Set-RegistryEntryValue -Path $reg.path -Name $reg.name -Type $reg.type -Value '<RemoveKey>'
                }
                elseif (-not $capReg.existed) {
                    if ($reg.originalValue -eq '<RemoveKey>') {
                        Set-RegistryEntryValue -Path $reg.path -Name $reg.name -Type $reg.type -Value '<RemoveKey>'
                    }
                    else {
                        Set-RegistryEntryValue -Path $reg.path -Name $reg.name -Type $reg.type -Value '<RemoveEntry>'
                    }
                }
                else {
                    $restoreType = if ($capReg.type) { $capReg.type } else { $reg.type }
                    Set-RegistryEntryValue -Path $reg.path -Name $reg.name -Type $restoreType -Value $capReg.value
                }
            }
            else {
                Set-RegistryEntryValue -Path $reg.path -Name $reg.name -Type $reg.type -Value $reg.originalValue
            }
        }

        Remove-CapturedState -Id $Id
        return $true
    }
}

# ============================================================================
# Module: src/windows/modules/game-engine.ps1
# ============================================================================
# Motor de Perfis de Jogos (VALORANT, Detec--o de Execut-vel, FSO/DPI, GPU Preference, NIC Anti-Jitter, Shader Cache)

$script:AllowedGameActions = @(
    'Set-AppCompatFlags',
    'Set-DirectXGpuPreference',
    'Optimize-NetworkAdapterGaming',
    'Disable-RiotClientStartup',
    'Clear-ShaderCache',
    'Optimize-UsbPower'
)

function Find-GameExecutable {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ProfileConfig,

        [string]$RiotInstallsPath
    )

    $det = $ProfileConfig.executableDetection
    if (-not $det) {
        return $null
    }

    foreach ($candidate in @($det.defaultPaths)) {
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate)) {
            return $candidate
        }
    }

    if (-not [string]::IsNullOrWhiteSpace($det.registryFallback)) {
        try {
            if (Test-Path -LiteralPath $det.registryFallback) {
                $props = Get-ItemProperty -LiteralPath $det.registryFallback -ErrorAction SilentlyContinue
                if ($props -and $props.InstallLocation) {
                    $baseLoc = $props.InstallLocation.Trim('"')
                    $exeFromReg = Join-Path $baseLoc 'ShooterGame\Binaries\Win64\VALORANT-Win64-Shipping.exe'
                    if (Test-Path -LiteralPath $exeFromReg) {
                        return $exeFromReg
                    }
                    $directExe = Get-ChildItem -Path $baseLoc -Filter '*-Win64-Shipping.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
                    if ($directExe) {
                        return $directExe.FullName
                    }
                }
            }
        }
        catch {
            Write-Verbose ("Erro no fallback de registro para jogo: {0}" -f $_.Exception.Message)
        }
    }

    if (-not $RiotInstallsPath) {
        $RiotInstallsPath = Join-Path $env:ProgramData 'Riot Games\RiotClientInstalls.json'
    }

    if (Test-Path -LiteralPath $RiotInstallsPath) {
        try {
            $riotJson = [System.IO.File]::ReadAllText($RiotInstallsPath, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
            if ($riotJson -and $riotJson.associated_client) {
                foreach ($prop in $riotJson.associated_client.PSObject.Properties) {
                    $installDir = ($prop.Name -replace '/', '\').TrimEnd('\')
                    if ($installDir -match '(?i)VALORANT') {
                        $candidateExe = Join-Path $installDir 'ShooterGame\Binaries\Win64\VALORANT-Win64-Shipping.exe'
                        if (Test-Path -LiteralPath $candidateExe) {
                            return $candidateExe
                        }
                    }
                }
            }
        }
        catch {
            Write-Verbose ("Erro ao ler RiotClientInstalls.json: {0}" -f $_.Exception.Message)
        }
    }

    return $null
}

function Set-AppCompatFlags {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$ExecutablePath,

        [string]$Flags = '~ DISABLEDXMAXIMIZEDWINDOWEDMODE HIGHDPIAWARE',

        [string]$StateKey = 'Val_FSO_HighDPI',

        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    $layersKey = 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers'
    if ($Mode -eq 'Apply') {
        $cur = Get-RegistryEntryState -Path $layersKey -Name $ExecutablePath -FallbackType 'String'
        Save-CapturedState -Id $StateKey -CapturedItems @(
            @{ kind = 'registry'; path = $layersKey; name = $ExecutablePath; existed = $cur.ValueExisted; type = 'String'; value = $cur.Value }
        )
        Set-RegistryEntryValue -Path $layersKey -Name $ExecutablePath -Type 'String' -Value $Flags
    }
    else {
        $cap = Get-CapturedState -Id $StateKey
        if ($cap -and $cap.captured -and $cap.captured.Count -gt 0 -and $cap.captured[0].existed) {
            Set-RegistryEntryValue -Path $layersKey -Name $ExecutablePath -Type 'String' -Value $cap.captured[0].value
        }
        else {
            Set-RegistryEntryValue -Path $layersKey -Name $ExecutablePath -Type 'String' -Value '<RemoveEntry>'
        }
        Remove-CapturedState -Id $StateKey
    }
}

function Set-DirectXGpuPreference {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$ExecutablePath,

        [string]$StateKey = 'Val_DirectX_HighPerf',

        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    $gpuKey = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
    $prefVal = 'GpuPreference=2;'

    if ($Mode -eq 'Apply') {
        $cur = Get-RegistryEntryState -Path $gpuKey -Name $ExecutablePath -FallbackType 'String'
        Save-CapturedState -Id $StateKey -CapturedItems @(
            @{ kind = 'registry'; path = $gpuKey; name = $ExecutablePath; existed = $cur.ValueExisted; type = 'String'; value = $cur.Value }
        )
        Set-RegistryEntryValue -Path $gpuKey -Name $ExecutablePath -Type 'String' -Value $prefVal
    }
    else {
        $cap = Get-CapturedState -Id $StateKey
        if ($cap -and $cap.captured -and $cap.captured.Count -gt 0 -and $cap.captured[0].existed) {
            Set-RegistryEntryValue -Path $gpuKey -Name $ExecutablePath -Type 'String' -Value $cap.captured[0].value
        }
        else {
            Set-RegistryEntryValue -Path $gpuKey -Name $ExecutablePath -Type 'String' -Value '<RemoveEntry>'
        }
        Remove-CapturedState -Id $StateKey
    }
}

function Optimize-NetworkAdapterGaming {
    [CmdletBinding()]
    param(
        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    $stateKey = 'NetworkAdapterGaming'
    $targetKeywords = @(
        '*EEE',
        'EEELinkAdvertisement',
        'AdvancedEEE',
        'GreenEthernet',
        'EnableGreenEthernet',
        'PowerSavingMode'
    )

    if ($Mode -eq 'Apply') {
        $capturedProps = New-Object 'System.Collections.Generic.List[hashtable]'
        if (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue) {
            $adapters = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }
            foreach ($nic in $adapters) {
                $advProps = Get-NetAdapterAdvancedProperty -Name $nic.Name -ErrorAction SilentlyContinue
                foreach ($ap in $advProps) {
                    if ($targetKeywords -contains $ap.RegistryKeyword) {
                        [void]$capturedProps.Add(@{
                            adapter = $nic.Name
                            keyword = $ap.RegistryKeyword
                            value   = $ap.RegistryValue
                        })
                    }
                }
            }
        }

        Save-CapturedState -Id $stateKey -CapturedItems $capturedProps.ToArray()

        Invoke-Mutation -Description 'Desativar EEE, Green Ethernet e economia de energia no adaptador de rede ativo' -Action {
            if (-not (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue)) {
                return
            }
            $adapters = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }
            foreach ($nic in $adapters) {
                $advProps = Get-NetAdapterAdvancedProperty -Name $nic.Name -ErrorAction SilentlyContinue
                foreach ($ap in $advProps) {
                    if ($targetKeywords -contains $ap.RegistryKeyword) {
                        Set-NetAdapterAdvancedProperty -Name $nic.Name -RegistryKeyword $ap.RegistryKeyword -RegistryValue 0 -NoRestart -ErrorAction SilentlyContinue
                    }
                }
                if (Get-Command Disable-NetAdapterPowerManagement -ErrorAction SilentlyContinue) {
                    Disable-NetAdapterPowerManagement -Name $nic.Name -NoRestart -ErrorAction SilentlyContinue
                }
            }
        } | Out-Null
    }
    else {
        $cap = Get-CapturedState -Id $stateKey
        Invoke-Mutation -Description 'Restaurar propriedades originais de energia do adaptador de rede' -Action {
            if ($cap -and $cap.captured) {
                foreach ($item in $cap.captured) {
                    if ($item.adapter -and $item.keyword -and $null -ne $item.value) {
                        Set-NetAdapterAdvancedProperty -Name $item.adapter -RegistryKeyword $item.keyword -RegistryValue $item.value -NoRestart -ErrorAction SilentlyContinue
                    }
                }
            }
            if (Get-Command Enable-NetAdapterPowerManagement -ErrorAction SilentlyContinue) {
                $adapters = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }
                foreach ($nic in $adapters) {
                    Enable-NetAdapterPowerManagement -Name $nic.Name -NoRestart -ErrorAction SilentlyContinue
                }
            }
        } | Out-Null
        Remove-CapturedState -Id $stateKey
    }
}

function Disable-RiotClientStartup {
    [CmdletBinding()]
    param(
        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    $runKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
    $approvedKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'
    $stateKey = 'Val_RiotClient_Cleanup'

    $entryNames = New-Object 'System.Collections.Generic.List[string]'
    if (Test-Path -LiteralPath $runKey) {
        $runItem = Get-Item -LiteralPath $runKey -ErrorAction SilentlyContinue
        if ($runItem) {
            foreach ($vn in $runItem.GetValueNames()) {
                $val = [string]$runItem.GetValue($vn, '')
                if ($vn -match '(?i)RiotClient' -or $val -match '(?i)RiotClientServices\.exe') {
                    [void]$entryNames.Add($vn)
                }
            }
        }
    }
    if ($entryNames.Count -eq 0) {
        [void]$entryNames.Add('RiotClient')
    }

    if ($Mode -eq 'Apply') {
        $capList = New-Object 'System.Collections.Generic.List[hashtable]'
        foreach ($en in $entryNames) {
            $curState = Get-RegistryEntryState -Path $approvedKey -Name $en -FallbackType 'Binary'
            [void]$capList.Add(@{
                kind    = 'startupApproved'
                name    = $en
                existed = $curState.ValueExisted
                value   = if ($curState.Value) { [Convert]::ToBase64String([byte[]]$curState.Value) } else { $null }
            })
        }
        Save-CapturedState -Id $stateKey -CapturedItems $capList.ToArray()

        $disabledBytes = [byte[]](0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
        Invoke-Mutation -Description "Desativar inicializa$([char]0x00E7)$([char]0x00E3)o autom$([char]0x00E1)tica do Riot Client via StartupApproved (mantendo Vanguard intacto)" -Action {
            if (-not (Test-Path -LiteralPath $approvedKey)) {
                New-Item -Path $approvedKey -Force | Out-Null
            }
            foreach ($en in $entryNames) {
                Set-ItemProperty -LiteralPath $approvedKey -Name $en -Value $disabledBytes -Type Binary -Force -ErrorAction Stop
            }
        } | Out-Null
    }
    else {
        $cap = Get-CapturedState -Id $stateKey
        $enabledBytes = [byte[]](0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
        Invoke-Mutation -Description "Reativar inicializa$([char]0x00E7)$([char]0x00E3)o autom$([char]0x00E1)tica do Riot Client no StartupApproved" -Action {
            if ($cap -and $cap.captured) {
                foreach ($item in $cap.captured) {
                    if ($item.existed -and $item.value) {
                        $origBytes = [Convert]::FromBase64String([string]$item.value)
                        Set-ItemProperty -LiteralPath $approvedKey -Name $item.name -Value $origBytes -Type Binary -Force -ErrorAction SilentlyContinue
                    }
                    elseif (Test-Path -LiteralPath $approvedKey) {
                        Set-ItemProperty -LiteralPath $approvedKey -Name $item.name -Value $enabledBytes -Type Binary -Force -ErrorAction SilentlyContinue
                    }
                }
            }
        } | Out-Null
        Remove-CapturedState -Id $stateKey
    }
}

function Clear-ShaderCache {
    [CmdletBinding()]
    param(
        [string[]]$TargetDirectories
    )

    if (-not $TargetDirectories -or $TargetDirectories.Count -eq 0) {
        $TargetDirectories = @(
            (Join-Path $env:LOCALAPPDATA 'D3DSCache'),
            (Join-Path $env:LOCALAPPDATA 'NVIDIA\DXCache'),
            (Join-Path $env:LOCALAPPDATA 'NVIDIA\GLCache'),
            (Join-Path $env:LOCALAPPDATA 'AMD\DxCache'),
            (Join-Path $env:LOCALAPPDATA 'AMD\DxcCache')
        )
    }

    Invoke-Mutation -Description "Limpar diret$([char]0x00F3)rios de Cache de Shaders (DirectX, NVIDIA e AMD)" -Action {
        $freedBytes = [int64]0
        $deletedCount = 0

        foreach ($dir in $TargetDirectories) {
            if (-not (Test-Path -LiteralPath $dir)) {
                continue
            }
            $files = Get-ChildItem -LiteralPath $dir -Recurse -File -Force -ErrorAction SilentlyContinue
            foreach ($f in $files) {
                $len = $f.Length
                try {
                    Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop
                    $freedBytes += $len
                    $deletedCount++
                }
                catch {
                    Write-Verbose ("Arquivo de cache em uso (ignorado): {0}" -f $f.FullName)
                }
            }
        }

        $freedMb = [math]::Round(($freedBytes / 1MB), 2)
        Write-OptimizerLog -Level OK -Message ("Cache de Shaders limpo: {0} arquivos removidos ({1} MB liberados)." -f $deletedCount, $freedMb)
    } | Out-Null
}

function Invoke-GameOptimization {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ProfileConfig,

        [Parameter(Mandatory = $true)]
        [pscustomobject]$Optimization,

        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply',

        [string]$CustomExePath
    )

    $action = $Optimization.action
    if ($script:AllowedGameActions -notcontains $action) {
        $msg = "Action '$action' na otimiza$([char]0x00E7)$([char]0x00E3)o '$($Optimization.id)' n$([char]0x00E3)o consta na whitelist do game-engine."
        Write-OptimizerLog -Level ERROR -Message $msg
        throw $msg
    }

    switch ($action) {
        'Set-AppCompatFlags' {
            $exe = if ($CustomExePath) { $CustomExePath } else { Find-GameExecutable -ProfileConfig $ProfileConfig }
            if ([string]::IsNullOrWhiteSpace($exe)) {
                Write-OptimizerLog -Level WARN -Message ("Execut$([char]0x00E1)vel de {0} n$([char]0x00E3)o encontrado para aplicar '{1}'." -f $ProfileConfig.gameName, $Optimization.title)
                return $false
            }
            $flags = if ($Optimization.flags) { $Optimization.flags } else { '~ DISABLEDXMAXIMIZEDWINDOWEDMODE HIGHDPIAWARE' }
            Set-AppCompatFlags -ExecutablePath $exe -Flags $flags -StateKey $Optimization.id -Mode $Mode
            return $true
        }
        'Set-DirectXGpuPreference' {
            $exe = if ($CustomExePath) { $CustomExePath } else { Find-GameExecutable -ProfileConfig $ProfileConfig }
            if ([string]::IsNullOrWhiteSpace($exe)) {
                Write-OptimizerLog -Level WARN -Message ("Execut$([char]0x00E1)vel de {0} n$([char]0x00E3)o encontrado para aplicar '{1}'." -f $ProfileConfig.gameName, $Optimization.title)
                return $false
            }
            Set-DirectXGpuPreference -ExecutablePath $exe -StateKey $Optimization.id -Mode $Mode
            return $true
        }
        'Optimize-NetworkAdapterGaming' {
            Optimize-NetworkAdapterGaming -Mode $Mode
            return $true
        }
        'Disable-RiotClientStartup' {
            Disable-RiotClientStartup -Mode $Mode
            return $true
        }
        'Clear-ShaderCache' {
            if ($Mode -eq 'Apply') {
                Clear-ShaderCache
            }
            else {
                Write-OptimizerLog -Level INFO -Message "A limpeza de Cache de Shaders $([char]0x00E9) uma opera$([char]0x00E7)$([char]0x00E3)o de manuten$([char]0x00E7)$([char]0x00E3)o (o driver recria o cache automaticamente)."
            }
            return $true
        }
        'Optimize-UsbPower' {
            if ($Mode -eq 'Apply') {
                Optimize-UsbPower
            }
            else {
                Restore-UsbPower
            }
            return $true
        }
    }

    return $false
}

function Test-GameOptimizationApplied {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ProfileConfig,

        [Parameter(Mandatory = $true)]
        [pscustomobject]$Optimization,

        [string]$CustomExePath
    )

    switch ($Optimization.action) {
        'Set-AppCompatFlags' {
            $exe = if ($CustomExePath) { $CustomExePath } else { Find-GameExecutable -ProfileConfig $ProfileConfig }
            if ([string]::IsNullOrWhiteSpace($exe)) { return $false }
            $layersKey = 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers'
            $st = Get-RegistryEntryState -Path $layersKey -Name $exe -FallbackType 'String'
            return ($st.ValueExisted -and ($st.Value -match 'DISABLEDXMAXIMIZEDWINDOWEDMODE'))
        }
        'Set-DirectXGpuPreference' {
            $exe = if ($CustomExePath) { $CustomExePath } else { Find-GameExecutable -ProfileConfig $ProfileConfig }
            if ([string]::IsNullOrWhiteSpace($exe)) { return $false }
            $gpuKey = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
            $st = Get-RegistryEntryState -Path $gpuKey -Name $exe -FallbackType 'String'
            return ($st.ValueExisted -and ($st.Value -match 'GpuPreference=2'))
        }
        'Optimize-NetworkAdapterGaming' {
            return ($null -ne (Get-CapturedState -Id 'NetworkAdapterGaming'))
        }
        'Disable-RiotClientStartup' {
            $approvedKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'
            $st = Get-RegistryEntryState -Path $approvedKey -Name 'RiotClient' -FallbackType 'Binary'
            if ($st.ValueExisted -and $st.Value -is [byte[]] -and $st.Value.Length -ge 1) {
                return ($st.Value[0] -eq 0x03)
            }
            return ($null -ne (Get-CapturedState -Id 'Val_RiotClient_Cleanup'))
        }
        'Optimize-UsbPower' {
            return (Test-UsbPowerOptimized)
        }
        default {
            return $false
        }
    }
}

